def prefixStencilsBossReceipt(readings, k):
    a=readings
    out=[]
    sums=[0]
    for x in a: sums.append(sums[-1]+x)
    for i in range(len(a)): out.append(sums[i+1]-sums[max(0,i-k+1)])
    return sum((i+1)*x for i,x in enumerate(out))

